    toadkin: [['글룩', '폴프', '머드', '크록'], ['웝', '고르', '블롭', '치', '뭄'], ['Gluk', 'Polp', 'Mud', 'Krok'], ['wop', 'gor', 'blob', 'chi', 'mum']],
    molekin: [['버로', '디그', '섀도', '벨벳'], ['위즐', '토', '노즈', '굴', '팜'], ['Burr', 'Dig', 'Shad', 'Velv'], ['wiz', 'to', 'nose', 'gul', 'pum']],
