    tigran: [['스트라이프', '샨', '펠', '로어'], ['클로', '파드', '타이거', '메인', '샤'], ['Stripe', 'Shan', 'Fel', 'Roar'], ['claw', 'pad', 'tiger', 'mane', 'sha']],
